/** Authored reasons to visit the compact chart. These are public facts, not Earth spoilers. */
const freeze=value=>{if(value&&typeof value==='object'){for(const child of Object.values(value))freeze(child);Object.freeze(value);}return value;};
const activity=(id,label,bodyId)=>({id,label,bodyId});
const profile=(id,role,description,activities,lanes,incidents)=>({id,role,description,activities,lanes,incidents});

