const byId=new Map(SYSTEM_IDENTITIES.map(profile=>[profile.id,profile]));

export function systemIdentity(system){return byId.get(typeof system==='string'?system:system?.id)||null;}

/** Apply on catalog construction; keep physical/catalog identity and the authored body list intact. */
export function applySystemIdentity(system){
 const identity=systemIdentity(system);return identity?{...system,description:identity.description,identityRole:identity.role,localActivities:identity.activities.map(activity=>({...activity}))}:system;
}

/** Apply after geographic/type policy. Protected hubs remain protected. */
export function applySystemIdentityContext(system,context){
 const identity=systemIdentity(system);if(!identity)return context;
 const lanes=identity.lanes;
 return {...context,...lanes,identityRole:identity.role,
  // Catalog role never overrides the core region's prohibition on random attacks.
  backgroundHostileCount:context.region==='core'?0:lanes.backgroundHostileCount,
  rescueSignalChance:context.region==='core'?Math.min(context.rescueSignalChance,lanes.rescueSignalChance):lanes.rescueSignalChance,
  derelictSignalChance:context.region==='core'?Math.min(context.derelictSignalChance,lanes.derelictSignalChance):lanes.derelictSignalChance};
}

/** Relative incident weights multiply existing regional eligibility; zero never becomes positive. */
export function systemIdentityIncidentWeight(system,type){return systemIdentity(system)?.incidents[type]??1;}
